#include "rclcpp/rclcpp.hpp"

namespace my_hw
{

/// Custom SystemInterface for a two-joint (revolute) robot.
/**
 * Each joint exposes a position command interface and position + velocity
 * state interfaces. The hardware simulates an ideal actuator: the commanded
 * position is integrated into the internal state on every write/read cycle,
 * so it is reflected back through the position state interface, with the
 * velocity state interface derived from the resulting position change.
 */
class MyHardware : public hardware_interface::SystemInterface
{
public:
  hardware_interface::CallbackReturn on_init(
    const hardware_interface::HardwareComponentInterfaceParams & params) override;

  hardware_interface::return_type read(
    const rclcpp::Time & time, const rclcpp::Duration & period) override;

  hardware_interface::return_type write(
    const rclcpp::Time & time, const rclcpp::Duration & period) override;

private:
  std::vector<std::string> joint_names_;

  std::unordered_map<std::string, double> hw_positions_;
  std::unordered_map<std::string, double> hw_velocities_;
  std::unordered_map<std::string, double> hw_commands_positions_;
};

}  // namespace my_hw

#endif  // MY_HW__MY_HW_HPP_

