#include "my_hw/my_hw.hpp"

#include "pluginlib/class_list_macros.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MyHardware::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  const auto base_ret = hardware_interface::SystemInterface::on_init(params);
  if (base_ret != hardware_interface::CallbackReturn::SUCCESS)
  {
    return base_ret;
  }

  for (const auto & joint : info_.joints)
  {
    joint_names_.push_back(joint.name);
    hw_positions_[joint.name] = 0.0;
    hw_velocities_[joint.name] = 0.0;
    hw_commands_positions_[joint.name] = 0.0;
  }

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHardware::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double period_s = period.seconds();

  for (const auto & joint_name : joint_names_)
  {
    // Integrate the last commanded position into the reported state, as if
    // an ideal actuator had instantaneously reached the commanded position.
    const double previous_position = hw_positions_[joint_name];
    const double new_position = hw_commands_positions_[joint_name];

    hw_velocities_[joint_name] =
      (period_s > 0.0) ? (new_position - previous_position) / period_s : 0.0;
    hw_positions_[joint_name] = new_position;

    set_state(joint_name + "/" + hardware_interface::HW_IF_POSITION, hw_positions_[joint_name]);
    set_state(joint_name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocities_[joint_name]);
  }

  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHardware::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  for (const auto & joint_name : joint_names_)
  {
    hw_commands_positions_[joint_name] =
      get_command(joint_name + "/" + hardware_interface::HW_IF_POSITION);
  }

  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

PLUGINLIB_EXPORT_CLASS(my_hw::MyHardware, hardware_interface::SystemInterface)

